#include <print>
#include <queue>
#include <vector>

int main() {
    const int LIM = 100;
    std::vector<int> dist(LIM, -1);
    std::queue<int> q;
    q.push(5); dist[5] = 0;
    while (!q.empty()) {
        int cur = q.front(); q.pop();
        for (int d : {-1, 1, 2, 3}) {
            int nxt = cur + d;
            if (d == 2) nxt = cur * 2;
            if (nxt < 0 || nxt >= LIM || dist[nxt] != -1) continue;
            dist[nxt] = dist[cur] + 1;
            q.push(nxt);
        }
    }
    std::println("dist[10] = {}", dist[10]);
    std::println("dist[18] = {}", dist[18]);
    std::println("加了 +3 这扇门，dist[17] = {}", dist[17]);
    return 0;
}
// 三扇门时 17 在第 4 圈，加了 +3 提前一圈，dist[17] 缩成 3

